#include <stdio.h>

int count_bits(unsigned int n) {
    int count = 0;
    while (n > 0) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

int main() {
    printf("%d\n", count_bits(13));
    printf("%d\n", count_bits(255));
    printf("%d\n", count_bits(1024));
    return 0;
}
